local M = {}

---新しい世代の公開（`init.lua` の付け替え）を監視する。`init.lua` がこの Neovim の
---起動した世代とは別の世代を指すようになると、新しい世代ごとに1回 `cb` をメインループで
---呼ぶ。呼んだ時点ですでに別の世代が公開されていれば、そのときも呼ぶ。
---`RSPLUG_GENERATION` で世代を固定して起動した Neovim では何もしない。
---@param cb fun(latest: string, current: string)  公開された世代 ID と、この Neovim の世代 ID
---@return { stop: fun() }
function M.watch(cb)
	local generation = package.loaded['_rsplug/generation']
	if type(generation) ~= 'table' or generation.root == nil or generation.pinned then
		return { stop = function() end }
	end
	local uv = vim.uv
	local init = generation.root .. '/init.lua'
	local last = generation.id
	local stopped = false
	local function check()
		if stopped then
			return
		end
		local link = uv.fs_readlink(init)
		local latest = link and vim.fn.fnamemodify(link, ':t:r')
		if latest and latest ~= last then
			last = latest
			if latest ~= generation.id then
				cb(latest, generation.id)
			end
		end
	end

	local event = assert(uv.new_fs_event())
	local timer = assert(uv.new_timer())
	-- init.lua は rename で置き換わるのでファイルではなくディレクトリを監視し、
	-- まとめて届く通知を少し待ってから1回だけ確かめる。
	event:start(generation.root, {}, function(err)
		if not err then
			timer:start(200, 0, vim.schedule_wrap(check))
		end
	end)
	vim.schedule(check)

	return {
		stop = function()
			if stopped then
				return
			end
			stopped = true
			event:stop()
			event:close()
			timer:stop()
			timer:close()
		end,
	}
end

return M
